'use strict';
(() => {
const {ATTRS,ALL,TIERS,CHAMPIONS,metricById,championByName}=window.ADC_DATA;
const STORE='adc-ascent-personal-v1';
const today=()=>new Date().toLocaleDateString('en-CA');
const uid=()=>`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`;
const initial=()=>({version:1,profile:{riotId:'',region:'EUW',goal:'MASTER',primary:'Jinx',secondary:"Kai'Sa",flex:'Ezreal'},matches:[],reviews:[],assessments:[],quests:[],settings:{focusMetric:'MEC-01.1'},createdAt:new Date().toISOString()});
let state;
try{state=JSON.parse(localStorage.getItem(STORE))||initial();if(!state||!Array.isArray(state.matches)||!Array.isArray(state.assessments)||!Array.isArray(state.reviews)||!Array.isArray(state.quests)||!state.profile)throw Error('invalid');}catch(e){state=initial();}
const ui={page:'search',attr:'MEC',metricId:'MEC-01.1',tier:0,champion:'Jinx',selectedMatch:'',modal:null,menu:false,videoUrl:null,videoName:'',videoTime:0,videoFile:null,championContractIndex:0,selectedTab:'performance',importJson:null};
const $=s=>document.querySelector(s);
const el=(tag,attributes={})=>Object.assign(document.createElement(tag),attributes);
const safe=str=>String(str??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const q=str=>safe(str).replace(/`/g,'&#96;');
const fmt=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:1});
const percent=(n,d)=>d>0?100*n/d:0;
const cap=(v,mi,ma)=>Math.max(mi,Math.min(ma,Number(v)||0));
const metricList=ALL.map(m=>`<option value="${m.id}">${safe(m.id)} · ${safe(m.name)}</option>`).join('');
const iconPaths={overview:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',swords:'<path d="m14.5 17.5-3-3L3 6V3h3l8.5 8.5"/><path d="m13 19 6-6"/><path d="m16 16 4 4"/><path d="m3 21 6-6"/><path d="m14 5 5-2 2 2-2 5"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15m6-12v15"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/>',brain:'<path d="M12 18V5a3 3 0 0 0-5.9-.6A4 4 0 0 0 4 11a4 4 0 0 0 2 7.5A4 4 0 0 0 12 18Zm0 0V5a3 3 0 0 1 5.9-.6A4 4 0 0 1 20 11a4 4 0 0 1-2 7.5A4 4 0 0 1 12 18Z"/>',chart:'<path d="M3 3v18h18"/><path d="m7 16 4-5 4 3 5-8"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20V4H6.5A2.5 2.5 0 0 0 4 6.5v13Z"/><path d="M4 19.5A2.5 2.5 0 0 0 6.5 22H20v-5"/>',video:'<rect x="3" y="5" width="18" height="14" rx="1"/><path d="m10 9 5 3-5 3z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="1"/><path d="M7 3v4m10-4v4M3 10h18"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.87l.06.06-1.9 1.9-.06-.06A1.7 1.7 0 0 0 16 18.4a1.7 1.7 0 0 0-1 .6 1.7 1.7 0 0 0-.5 1.12V21h-2.7v-.1a1.7 1.7 0 0 0-1.1-1.6 1.7 1.7 0 0 0-1.8.4l-.1.1-1.9-1.9.1-.1a1.7 1.7 0 0 0-.4-1.8A1.7 1.7 0 0 0 5 15H4v-3h1a1.7 1.7 0 0 0 1.6-1.1 1.7 1.7 0 0 0-.4-1.8L6.1 9l1.9-1.9.1.1a1.7 1.7 0 0 0 1.8.4A1.7 1.7 0 0 0 11 6V5h3v1a1.7 1.7 0 0 0 1.1 1.6 1.7 1.7 0 0 0 1.8-.4l.1-.1L18.9 9l-.1.1a1.7 1.7 0 0 0-.4 1.8A1.7 1.7 0 0 0 20 12h1v3h-1.6Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="m5 12 14 0m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',trash:'<path d="M3 6h18M8 6V4h8v2m-10 0 1 15h10l1-15M10 10v7m4-7v7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',play:'<path d="m8 5 12 7-12 7V5Z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',up:'<path d="m7 14 5-5 5 5"/>',spark:'<path d="m12 2 2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2L12 2Z"/>'};
const icon=(name,size=18)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${iconPaths[name]||iconPaths.target}</svg>`;
const save=()=>{try{localStorage.setItem(STORE,JSON.stringify(state));}catch(e){toast('Local storage full. Export your data in Settings.');}};
let toastTimer;function toast(msg){const target=$('#toast');if(!target)return;target.textContent=msg;target.classList.add('toast','show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>target.classList.remove('show'),3500);}
const navs=[['search','Find Player','target'],['analytics','Analytics Hub','chart'],['overview','Training Command','overview'],['tree','Skill Tree','target'],['champions','Champion Forge','shield'],['training','Training Plan','calendar'],['matches','Match History','chart'],['recorder','Capture Studio','video'],['mechanics','Mechanics Lab','target'],['vod','VOD Review Lab','video'],['insights','Performance Insights','brain'],['settings','Settings & Data','settings']];
const pageLabel=()=>navs.find(n=>n[0]===ui.page)?.[1]||'Command Center';
const nextTier=t=>t<9?TIERS[t+1].name:'MAX';
const rankLabel=i=>i<0?'UNASSESSED':TIERS[Math.min(i,9)].name;
function qualificationFor(key,tier){const rule=TIERS[tier];return state.assessments.some(a=>a.key===key&&a.tier===tier&&a.successes>=0&&a.opportunities>=rule.count&&a.sessions>=rule.sessions&&percent(a.successes,a.opportunities)>=rule.accuracy&&a.source&&a.date);}
function certified(key){let tier=-1;for(let i=0;i<TIERS.length;i++){if(qualificationFor(key,i))tier=i;else break;}return tier;}
const componentRank=c=>Math.min(...c.metrics.map(m=>certified(m.id)));
const attributeRank=a=>Math.min(...a.components.map(componentRank));
const overallRank=()=>Math.min(...ATTRS.map(attributeRank));
const completedCount=()=>state.quests.filter(q=>q.done).length;
const xp=()=>state.quests.filter(q=>q.done).reduce((sum,q)=>sum+(q.xp||0),0);
const recent=()=>[...state.matches].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,8);
const winrate=matches=>matches.length?percent(matches.filter(m=>m.win).length,matches.length):null;
const avgCs=matches=>matches.length?matches.reduce((t,m)=>t+((+m.cs||0)/Math.max(1,+m.duration||30)),0)/matches.length:null;
const reviewSuccess=r=>Number(r.rating)>=3;
const weekly=()=>{const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-i);const stamp=d.toLocaleDateString('en-CA');days.push({date:stamp,label:d.toLocaleDateString('en-US',{weekday:'short'}),matches:state.matches.filter(m=>m.date===stamp).length,quests:state.quests.filter(x=>x.date===stamp&&x.done).length});}return days;};
const section=(title,body,aside='',extra='')=>`<section class="panel ${extra}"><div class="panel-header"><h3 class="panel-title">${title}</h3>${aside}</div><div class="panel-body">${body}</div></section>`;
const empty=(title,desc,action='')=>`<div class="empty"><div class="empty-mark">◇</div><b>${title}</b><p>${desc}</p>${action}</div>`;
const rankTag=(rank,extra='')=>`<span class="rank-tag ${rank<0?'empty':rank>=6?'high':''} ${extra}">${rankLabel(rank)}</span>`;
const stat=(label,value,hint,cls='')=>`<div class="panel stat"><small>${label}</small><div class="value ${cls}">${value}</div><div class="hint">${hint}</div></div>`;
const getMatches=()=>[...state.matches].sort((a,b)=>(b.date||'').localeCompare(a.date||''));
function buildShell(){const nav=navs.map(([id,label,ico])=>`<button type="button" class="nav-link ${ui.page===id?'active':''}" data-nav="${id}">${icon(ico)}<span>${label}</span></button>`);const active=pageLabel();return `<div class="mobile-backdrop ${ui.menu?'open':''}" data-action="close-menu"></div><div class="app-shell"><aside class="sidebar ${ui.menu?'open':''}"><div class="brand"><div class="brand-mark">A</div><div><div class="brand-title">ADC <span class="tint">ASCENT</span></div><div class="brand-sub">PERSONAL MASTERY STUDIO</div></div></div><div class="nav-group"><div class="nav-label">THE ASCENSION PATH</div>${nav.slice(0,6).join('')}</div><div class="nav-group"><div class="nav-label">INTELLIGENCE & REVIEW</div>${nav.slice(6,11).join('')}</div><div class="nav-group">${nav[11]}</div><div class="sidebar-bottom"><div class="sidemeta"><div class="eyebrow">PRIVATE TRAINING PROFILE</div><strong>${safe(state.profile.primary)} / ${safe(state.profile.secondary)}</strong><span>${state.matches.length} matches tracked · ${state.reviews.length} decisions reviewed</span></div></div></aside><div class="main-wrap"><header class="topbar"><div class="flat-row" style="justify-content:flex-start;gap:13px"><button class="mobile-menu" aria-label="Open navigation" data-action="toggle-menu">${icon('menu')}</button><div class="crumbs">ADC ASCENT <span>›</span> <b>${safe(active.toUpperCase())}</b></div></div><div class="top-actions"><span class="top-pill"><span class="live-dot"></span> LOCAL PROFILE</span><span class="date-chip">${new Date().toLocaleDateString('en-US',{day:'2-digit',month:'short',year:'numeric'}).toUpperCase()}</span></div></header><main class="content">${pageRender()}<footer class="footer">ADC ASCENT is an independently developed personal training tool and is not endorsed by Riot Games. Assessments are self-recorded and are not official League of Legends ranks or MMR. Data is saved only in this browser unless you export it.</footer></main></div></div>`;}
const pageIntro=(eye,title,desc,buttons='')=>`<div class="page-intro"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${desc}</p></div>${buttons?`<div class="actions">${buttons}</div>`:''}</div>`;
function pageRender(){switch(ui.page){case'search':return window.ADC_PROFILE_UI?.page(state.profile)||'<p>Player search unavailable</p>';case'analytics':return window.ADC_ANALYTICS_UI?.page(state.matches,state.profile)||'<p>Analytics Hub unavailable</p>';case'tree':return treePage();case'champions':return championPage();case'training':return trainingPage();case'matches':return matchesPage();case'vod':return vodPage();case'mechanics':return window.ADC_MECHANICS?.page(state.matches)||'<p>Mechanics Lab unavailable</p>';case'recorder':return window.ADC_CAPTURE?.page(state.profile)||'<p>Capture Studio unavailable</p>'; case'insights':return insightsPage()+(window.ADC_INTELLIGENCE_UI?.panel(state.matches)||'');case'settings':return settingsPage();default:return overviewPage();}}
function render(){const current=$('#vod-video');if(current&&Number.isFinite(current.currentTime))ui.videoTime=current.currentTime;$('#app').innerHTML=buildShell();renderModal();if(ui.page==='vod'&&ui.videoUrl){const video=$('#vod-video');if(video){video.src=ui.videoUrl;video.addEventListener('loadedmetadata',()=>{if(Number.isFinite(ui.videoTime)&&ui.videoTime>0)video.currentTime=Math.min(ui.videoTime,Math.max(0,video.duration-0.1));},{once:true});}}}
window.adcAppRender=()=>render();
function goto(page){ui.page=navs.some(n=>n[0]===page)?page:'overview';ui.menu=false;ui.modal=null;location.hash=ui.page;window.scrollTo(0,0);render();}
function chartWeek(){const days=weekly();const max=Math.max(1,...days.map(d=>d.matches));return `<div class="chart-bars">${days.map(d=>`<div class="chart-column"><div class="chart-bar" title="${d.matches} matches" style="height:${d.matches?Math.max(8,d.matches/max*124):2}px"></div><span class="chart-label">${d.label}</span></div>`).join('')}</div><div class="flat-row margintop"><span class="help">Matches logged · last 7 days</span><span class="tinycaps">${days.reduce((n,d)=>n+d.matches,0)} GAMES</span></div>`;}
function overviewPage(){const m=state.matches.filter(x=>x.isADC!==false), last=recent(), wr=winrate(m), cs=avgCs(m), rank=overallRank(), task=state.quests.filter(x=>x.date===today()), done=task.filter(x=>x.done), target=metricById(state.settings.focusMetric)||ALL[0], comp=ATTRS.flatMap(a=>a.components).find(c=>c.id===target.component);return `${pageIntro('SOLO QUEUE / DEVELOPMENT COMMAND','Your road to Master','A single place to train your ADC fundamentals, review match decisions and show real evidence of improvement.',`<button class="btn" data-nav="training">${icon('target',15)} Today’s training</button><button class="btn ghost" data-nav="search">Find Riot profile</button>`)}<div class="grid" style="gap:17px"><div class="panel hero"><div class="hero-head"><div><div class="eyebrow">ACTIVE SPECIALIZATION / ADC</div><h2>ASCEND THROUGH <span class="tint">EXECUTION</span></h2><p>Primary ${safe(state.profile.primary)} · Secondary ${safe(state.profile.secondary)}${state.profile.flex?' · Flex '+safe(state.profile.flex):''}. Turn weaknesses into targeted training and prove corrections in later games.</p><div class="hero-lines">${(state.profile.ranked||[]).filter(r=>r.queueType==='RANKED_SOLO_5x5').map(r=>`<span class="chip">RIOT SOLO · ${safe(r.tier)} ${safe(r.rank)} · ${safe(r.leaguePoints)} LP</span>`).join('')}<span class="chip">${icon('target',13)} ${safe(state.profile.goal)} OBJECTIVE</span><span class="chip muted-chip">${icon('shield',13)} ${rank<0?'ASSESSMENT PENDING':rankLabel(rank)+' CURRICULUM'}</span><span class="chip muted-chip">${icon('spark',13)} ${fmt(xp())} PRACTICE XP</span></div></div><div class="rank-emblem"><strong>${rank<0?'—':rankLabel(rank)}</strong><span>CURRICULUM</span></div></div></div><div class="grid cols4">${stat('Matches recorded',fmt(m.length),'ADC games only · all roles archived')}${stat('Match win rate',wr===null?'—':wr.toFixed(1)+'%',m.length?`${m.filter(x=>x.win).length} W / ${m.filter(x=>!x.win).length} L`:'Requires match data','good')}${stat('Average CS / min',cs===null?'—':cs.toFixed(2),'Not a stand-alone skill rating')}${stat('Review observations',fmt(state.reviews.length),'Decision-level coaching evidence')}</div><div class="grid cols2">${section('ACTIVE TRAINING FOCUS',`<div class="eyebrow">${safe(target.id)} / ${safe(target.componentName)}</div><h2 class="margintop">${safe(target.name)}</h2><p class="metric-desc margintop">${safe(target.definition)}</p><div class="flat-row margintop"><span class="chip muted-chip">${rankLabel(certified(target.id))} metric gate</span><button class="btn sm" data-nav="training">OPEN TRAINING ${icon('arrow',13)}</button></div><hr class="separator"><div class="tinycaps">TODAY'S CHECKLIST</div>${task.length?`<div class="margintop"><div class="flat-row small"><span>${done.length}/${task.length} quests complete</span><span class="tint">${Math.round(percent(done.length,task.length))}%</span></div><div class="progress-track margintop"><div class="progress-fill" style="width:${percent(done.length,task.length)}%"></div></div></div>`:`<p class="help margintop">No daily mission yet. Create one in Training Plan.</p>`}`,`<span class="chip muted-chip">${safe(comp?.name||'FOCUS')}</span>`)}${section('THE LAST 7 DAYS',chartWeek(),`<span class="tinycaps">MATCH ACTIVITY</span>`)}${section('RECENT MATCHES',last.length?last.slice(0,4).map(x=>`<div class="list-row"><span class="result ${x.win?'win':'loss'}">${x.win?'W':'L'}</span><div class="list-row-main"><strong>${safe(x.champion)}</strong><p>${safe(x.date)} · ${fmt(x.kills)}/${fmt(x.deaths)}/${fmt(x.assists)} · ${fmt(x.cs)} CS</p></div><span class="row-meta">${(+x.cs/Math.max(1,+x.duration)).toFixed(1)} CS/M</span></div>`).join(''):empty('No matches yet','Add your first game to create a real performance baseline.',`<button class="btn sm" data-action="add-match">Log first match</button>`),`<button class="text-action" data-nav="matches">ALL MATCHES ${icon('arrow',12)}</button>`)}${section('MASTERY PATH',ATTRS.map(a=>{let r=attributeRank(a);let progress=a.components.reduce((n,c)=>n+c.metrics.filter(m=>certified(m.id)>=0).length,0);return `<div class="list-row"><div style="width:38px;color:var(--cyan)">${icon(a.icon,23)}</div><div class="list-row-main"><strong>${safe(a.name)}</strong><p>${progress}/9 metrics have documented F-gate evidence</p><div class="progress-track" style="margin-top:10px;height:4px"><div class="progress-fill" style="width:${progress/9*100}%"></div></div></div>${rankTag(r)}</div>`}).join(''),`<button class="text-action" data-nav="tree">OPEN TREE ${icon('arrow',12)}</button>`)}</div></div>`;}
function treePage(){const attr=ATTRS.find(a=>a.id===ui.attr)||ATTRS[0], active=metricById(ui.metricId);if(!active||active.attribute!==attr.id)ui.metricId=attr.components[0].metrics[0].id;const metric=metricById(ui.metricId);const stage=TIERS[ui.tier];const tier=certified(metric.id);const comp=attr.components.find(c=>c.id===metric.component);const eligible=qualificationFor(metric.id,ui.tier);return `${pageIntro('SYSTEM / 45 SKILL METRICS','ADC mastery tree','Five attributes. Fifteen ranked components. Forty-five measurable skills. Each skill has ten increasingly demanding assessments.',`<button class="btn" data-action="assess-metric" data-id="${metric.id}">${icon('plus',14)} Add assessment</button>`)}<div class="grid cols4" style="margin-bottom:17px">${stat('Attributes','05','Independent skill domains')}${stat('Components','15','Require three metric gates')}${stat('Metrics','45','450 difficulty tasks')}${stat('Overall curriculum',rankLabel(overallRank()),'Lowest qualifying attribute','gold')}</div><div class="attribute-row marginbottom">${ATTRS.map(a=>`<button class="attr-btn ${a.id===ui.attr?'active':''}" data-attr="${a.id}">${a.id} · ${safe(a.name)}</button>`).join('')}</div><div class="grid cols2"><section class="panel"><div class="panel-header"><div><div class="eyebrow">ATTRIBUTE / ${safe(attr.id)}</div><h3 class="panel-title">${safe(attr.name.toUpperCase())}</h3></div>${rankTag(attributeRank(attr))}</div><div class="panel-body"><p class="metric-desc marginbottom">${safe(attr.description)}</p>${attr.components.map(c=>`<div class="component-head"><h3>${safe(c.name)}</h3>${rankTag(componentRank(c))}</div>${c.metrics.map(m=>`<button class="metric-line ${m.id===ui.metricId?'selected':''}" data-metric="${m.id}" style="width:100%;text-align:left"><span><b>${safe(m.name)}</b><small>${safe(m.definition)}</small></span><span class="code">${safe(m.id)}</span></button>`).join('')}<hr class="separator">`).join('')}</div></section><section class="panel"><div class="panel-header"><div><div class="eyebrow">METRIC ANALYSIS / ${safe(metric.id)}</div><h3 class="panel-title">${safe(metric.name)}</h3></div><span class="chip muted-chip">${safe(metric.source)}</span></div><div class="panel-body"><p class="metric-desc">${safe(metric.definition)}</p><div class="flat-row margintop"><span class="tinycaps">Highest completed gate</span>${rankTag(tier)}</div><hr class="separator"><div class="tinycaps marginbottom">F → MONARCH CHALLENGE PATH</div><div class="tier-grid">${TIERS.map((t,i)=>`<button class="tier-button ${i===ui.tier?'active':''}" data-tier="${i}" aria-pressed="${i===ui.tier}">${t.name}</button>`).join('')}</div><div class="gate-box"><div class="flat-row"><span class="eyebrow">DIFFICULTY ${ui.tier+1} / 10</span><span class="chip ${eligible?'success':'muted-chip'}">${eligible?'RECORDED PASS':'NEEDS EVIDENCE'}</span></div><h3>${safe(stage.name)} Gate · ${safe(metric.name)}</h3><p>Demonstrate that you can <b>${safe(metric.challenge)}</b> ${safe(stage.context)}.</p><div class="detail-3"><div><small>SUCCESS RATE</small><b>${stage.accuracy}%</b></div><div><small>OPPORTUNITIES</small><b>${stage.count}</b></div><div><small>SESSIONS</small><b>${stage.sessions}</b></div></div></div><div class="flat-row margintop"><button class="btn" data-action="assess-metric" data-id="${metric.id}">${icon('plus',14)} Record gate result</button><button class="btn ghost" data-action="focus-metric" data-id="${metric.id}">Set as focus</button></div><hr class="separator"><div class="tinycaps marginbottom">ASSESSMENT HISTORY</div>${assessmentHistory(metric.id)}</div></section></div><div class="note margintop">A metric records test results; components earn curriculum tiers only when all three metrics pass each prerequisite gate. No F → Monarch tier is equivalent to an official Riot rank. Self-attested results remain provisional.</div>`;}
function assessmentHistory(key){const entries=state.assessments.filter(a=>a.key===key).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return entries.length?entries.slice(0,5).map(a=>`<div class="list-row"><div class="list-row-main"><strong>${safe(TIERS[a.tier]?.name||'?')} attempt · ${fmt(a.successes)}/${fmt(a.opportunities)} correct</strong><p>${safe(a.date)} · ${safe(a.source)} · ${fmt(a.sessions)} sessions</p></div><span class="chip ${qualificationFor(key,a.tier)?'success':'muted-chip'}">${percent(a.successes,a.opportunities).toFixed(0)}%</span><button class="text-action" data-action="delete-assessment" data-id="${a.id}" aria-label="Delete assessment">${icon('trash',14)}</button></div>`).join(''):empty('No assessments','Complete an appropriate practice drill or review, then record the observations.');}
function championPage(){const p=state.profile;const name=ui.champion||p.primary;const champion=championByName(name)||CHAMPIONS[0];ui.champion=champion.name;const tierNames=champion.contracts.map((x,i)=>({name:x,key:`C:${champion.name}:${i+1}`,tier:certified(`C:${champion.name}:${i+1}`)}));const cr=Math.min(...tierNames.map(x=>x.tier));const slotButtons=[['primary',p.primary,'PRIMARY'],['secondary',p.secondary,'SECONDARY'],['flex',p.flex,'FLEX']].filter(x=>x[1]).map(([slot,c,label])=>`<button class="attr-btn ${ui.champion===c?'active':''}" data-champion="${safe(c)}">${label} · ${safe(c)}</button>`).join('');return `${pageIntro('CHAMPION SPECIALIZATION / CONTRACT SYSTEM','Champion Forge','One deep primary, one reliable secondary and an optional flex. Each champion has six separate mastery contracts.',`<button class="btn" data-action="edit-pool">${icon('settings',14)} Edit champion pool</button>`)}<div class="panel hero marginbottom"><div class="hero-head"><div><div class="eyebrow">ACTIVE CHAMPION / ${safe(champion.type)}</div><h2>${safe(champion.name.toUpperCase())}</h2><p>Champion-specific evaluations feed your ADC curriculum, without duplicating practice XP. Contracts are tracked independently across all ten assessment tiers.</p><div class="hero-lines"><span class="chip">${tierNames.filter(x=>x.tier>=0).length}/6 F GATES</span><span class="chip muted-chip">${rankLabel(cr)} CONTRACT STATUS</span><span class="chip warn">PROVISIONAL EVIDENCE</span></div></div><div class="rank-emblem"><strong>${rankLabel(cr)==='UNASSESSED'?'—':rankLabel(cr)}</strong><span>CHAMPION</span></div></div></div><div class="attribute-row marginbottom">${slotButtons}</div><div class="grid cols2"><section class="panel"><div class="panel-header"><h3 class="panel-title">SIX MASTERY CONTRACTS</h3><span class="tinycaps">${safe(champion.name)}</span></div><div class="panel-body">${tierNames.map((c,i)=>`<button class="metric-line ${ui.championContractIndex===i?'selected':''}" style="width:100%;text-align:left" data-contract="${i}"><span><span class="code">CONTRACT C${i+1}</span><b style="margin-top:5px">${safe(c.name)}</b><small>${['Signature champion ability mastery','Champion-specific early lane application','Power-spike and item planning','Champion-specific damage execution','Survival and positioning discipline','Matchup adaptation and team composition'][i]}</small></span>${rankTag(c.tier)}</button>`).join('')}</div></section>${section('CONTRACT ASSESSMENT',(()=>{const i=ui.championContractIndex,c=tierNames[i];return `<div class="eyebrow">${safe(champion.name)} / C${i+1}</div><h2 class="margintop">${safe(c.name)}</h2><p class="metric-desc margintop">Train <b>${safe(c.name)}</b> through a champion-specific controlled scenario and demonstrate the same skill in post-game reviewed footage.</p><div class="flat-row margintop"><span class="tinycaps">Contract tier</span>${rankTag(c.tier)}</div><hr class="separator"><div class="tinycaps marginbottom">ASSESSMENT TIER</div><div class="tier-grid">${TIERS.map((t,j)=>`<button class="tier-button ${ui.tier===j?'active':''}" data-tier="${j}">${t.name}</button>`).join('')}</div><div class="gate-box"><span class="eyebrow">${safe(TIERS[ui.tier].name)} / C${i+1}</span><h3>${safe(c.name)} — ${safe(TIERS[ui.tier].name)}</h3><p>Demonstrate champion-specific <b>${safe(c.name.toLowerCase())}</b> ${safe(TIERS[ui.tier].context)}.</p><div class="detail-3"><div><small>SUCCESS</small><b>${TIERS[ui.tier].accuracy}%</b></div><div><small>OBSERVATIONS</small><b>${TIERS[ui.tier].count}</b></div><div><small>SESSIONS</small><b>${TIERS[ui.tier].sessions}</b></div></div></div><div class="flat-row margintop"><button class="btn" data-action="assess-contract" data-id="${safe(c.key)}">${icon('plus',14)} Record contract trial</button><button class="btn ghost" data-nav="vod">OPEN VOD LAB</button></div><hr class="separator">${assessmentHistory(c.key)}`})())}</div><div class="note margintop">Pool policy: the primary champion must develop all six contracts; secondary progression prioritizes signature execution, lane identity, survival and adaptation. Flex is optional. Trials use proposed ARISE curriculum thresholds, not Riot champion mastery points.</div>`;}
function createQuests(){const metric=metricById(state.settings.focusMetric)||ALL[0],day=today();state.quests=state.quests.filter(q=>q.date!==day);const tasks=[['FOCUSED DRILL',`Practice ${metric.name} in a controlled drill or scenario; record your attempt.`,25],['MATCH APPLICATION',`Play and log an ADC match with ${metric.name} as the primary learning target.`,35],['REVIEW ONE DECISION',`Review one decision linked to ${metric.name} in the VOD Lab.`,35],['REFLECTION',`Write a specific correction or practice takeaway for ${metric.name}.`,15]];tasks.forEach((t,i)=>state.quests.push({id:uid(),date:day,index:i,name:t[0],detail:t[1],xp:t[2],done:false,focus:metric.id,reflection:''}));save();}
function trainingPage(){const current=state.quests.filter(q=>q.date===today());const done=current.filter(q=>q.done).length;const f=metricById(state.settings.focusMetric)||ALL[0];const sessions=[...state.quests].filter(q=>q.done);return `${pageIntro('PERSONAL CURRICULUM / DAILY PRACTICE','Training Plan','Work on one primary weakness at a time. Practice grants XP; only valid, difficulty-matched assessments advance the mastery tree.',`<button class="btn" data-action="generate-training">${icon('plus',14)} ${current.length?'Regenerate today':'Create today’s mission'}</button>`)}<div class="grid cols3 marginbottom">${stat('Practice XP',fmt(xp()),'Earned from completed training quests','gold')}${stat('Quests completed',fmt(completedCount()),'Lifetime practice tasks')}${stat('Today’s execution',current.length?Math.round(percent(done,current.length))+'%':'—',current.length?`${done}/${current.length} required actions`:'Create your plan first')}</div><div class="grid cols2">${section('PRIMARY DEVELOPMENT TARGET',`<div class="eyebrow">FOCUS SELECTION</div><h2 class="margintop">${safe(f.name)}</h2><p class="metric-desc margintop">${safe(f.definition)}</p><div class="field margintop"><label for="focus-select">Choose a skill to train</label><select id="focus-select" data-change="focus" class="input">${metricList}</select></div><div class="note margintop">Select your training focus, then generate a mission. Creating a new mission replaces only today's checklist; older training history stays intact.</div>`,`<span class="chip muted-chip">${safe(f.component)}</span>`)}${section('TODAY’S TRAINING DIRECTIVE',current.length?`<div class="flat-row"><span class="tinycaps">${today()} · PRIMARY QUESTS</span><strong class="tint">${done}/${current.length}</strong></div><div class="progress-track margintop marginbottom"><div class="progress-fill" style="width:${percent(done,current.length)}%"></div></div>${current.map(q=>`<label class="checkbox-row ${q.done?'completed':''}"><input type="checkbox" data-quest="${q.id}" ${q.done?'checked':''}/><div><strong>${safe(q.name)}</strong><p>${safe(q.detail)}</p></div><small>+${q.xp} XP</small></label>`).join('')}${current.find(q=>q.index===3)?`<div class="field margintop"><label for="reflection">Practice reflection</label><textarea id="reflection" placeholder="What one decision will you make differently next game?" data-change="reflection">${safe(current.find(q=>q.index===3)?.reflection||'')}</textarea></div>`:''}`:empty('No mission scheduled','Create a focused practice mission around a measurable ADC skill.',`<button class="btn sm" data-action="generate-training">Build my plan</button>`),`<span class="chip muted-chip">${done} COMPLETED</span>`)}${section('ASSESSMENT PROTOCOL',`<div class="step"><div class="step-num">01</div><div><strong>Train a specific skill</strong><p>Use a drill or actual match, not unfocused repeated games.</p></div></div><div class="step"><div class="step-num">02</div><div><strong>Capture review evidence</strong><p>Use match events and timestamped VOD decisions to justify the score.</p></div></div><div class="step"><div class="step-num">03</div><div><strong>Submit a difficulty-gated trial</strong><p>Meet the minimum accuracy, eligible opportunities, and distinct sessions.</p></div></div><div class="step"><div class="step-num">04</div><div><strong>Transfer to subsequent matches</strong><p>Reassess similar situations and look for lasting correction.</p></div></div>`)}${section('RECENT PRACTICE HISTORY',sessions.length?sessions.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,8).map(x=>`<div class="list-row"><div class="list-row-main"><strong>${safe(x.name)}</strong><p>${safe(x.date)} · ${safe(metricById(x.focus)?.name||'ADC focus')}</p></div><span class="good row-meta">+${x.xp} XP</span></div>`).join(''):empty('Your practice history starts here','Complete training tasks to build a consistent practice record.'),`<span class="tinycaps">${fmt(sessions.length)} COMPLETED</span>`)}</div>`;}
function matchesPage(){const matches=getMatches(),wr=winrate(matches),cs=avgCs(matches);return `${pageIntro('RANKED INTELLIGENCE / MATCH HISTORY','Match Archive','Track actual games without exaggerating what the data proves. Add matches manually or import an exported Riot match-v5 JSON file.',`<button class="btn" data-action="add-match">${icon('plus',14)} Add match</button><button class="btn ghost" data-action="riot-json">${icon('download',14)} Import Riot JSON</button>`)}<div class="grid cols4 marginbottom">${stat('Total games',matches.length,'Recorded matches')}${stat('Win rate',wr===null?'—':wr.toFixed(1)+'%','Wins / all matches')}${stat('Avg CS/min',cs===null?'—':cs.toFixed(2),'Observed farm rate')}${stat('Average deaths',matches.length?(matches.reduce((t,m)=>t+(+m.deaths||0),0)/matches.length).toFixed(2):'—','Outcome indicator, not a rank')}</div>${section('MATCH LOG',matches.length?`<div class="table-wrap"><table class="matches-table"><thead><tr><th>Date</th><th>Champion</th><th>Result</th><th>K / D / A</th><th>CS</th><th>CS/min</th><th>Duration</th><th></th></tr></thead><tbody>${matches.map(m=>`<tr><td>${safe(m.date)}</td><td><b>${safe(m.champion)}</b></td><td><span class="result ${m.win?'win':'loss'}">${m.win?'VICTORY':'DEFEAT'}</span></td><td>${fmt(m.kills)} / ${fmt(m.deaths)} / ${fmt(m.assists)}</td><td>${fmt(m.cs)}</td><td>${(+m.cs/Math.max(1,+m.duration)).toFixed(1)}</td><td>${(+m.duration).toFixed(0)}m</td><td><button class="text-action" data-action="match-detail" data-id="${m.id}">DETAIL</button></td></tr>`).join('')}</tbody></table></div>`:empty('No recorded matches','Add a ranked or normal ADC game. Your performance graphs will populate automatically.',`<button class="btn sm" data-action="add-match">Add first match</button>`),`<button class="text-action" data-action="export-csv">EXPORT CSV ${icon('download',13)}</button>`)}<div class="note margintop">Riot account authentication and automatic match synchronization are not connected in this offline-first version. Riot match-v5 JSON is supported for importing selected participant statistics; it cannot reveal your in-game dodges, wave choices or all decision errors.</div>`;}
function vodPage(){const reviews=[...state.reviews].sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));const m=ui.selectedMatch||'';return `${pageIntro('MATCH LAB / DECISION INTELLIGENCE','VOD Review Lab','Study why a play happened, tag precise decisions and convert recurring errors into skill-specific training.',`<button class="btn ghost" data-nav="tree">${icon('target',15)} Skill tree</button>`)}<div class="grid cols2"><section class="panel"><div class="panel-header"><h3 class="panel-title">REPLAY WORKSPACE</h3><span class="chip muted-chip">LOCAL VIDEO</span></div><div class="panel-body"><div class="field marginbottom"><label for="vod-file">Open an MP4/WebM clip from your device</label><input type="file" id="vod-file" accept="video/mp4,video/webm,video/ogg"/></div>${ui.videoUrl?`<video id="vod-video" class="video-player" controls preload="metadata" playsinline></video><div class="flat-row margintop"><span class="muted small">${safe(ui.videoName)} · not uploaded</span><button class="text-action" data-action="clear-video">CLEAR VIDEO</button></div>`:`<div class="video-placeholder"><div><div class="film-icon">▷</div><strong>YOUR MATCH FOOTAGE</strong><span>Select a local clip to play and annotate</span></div></div>`}<div class="field margintop"><label for="review-match">Linked match (optional)</label><select id="review-match" class="input" data-change="review-match"><option value="">No match linked</option>${getMatches().map(m=>`<option value="${m.id}">${safe(m.date)} · ${safe(m.champion)} · ${m.win?'Win':'Loss'}</option>`).join('')}</select></div>${ui.videoUrl?`<button class="btn sm margintop" data-action="capture-time">${icon('clock',13)} Use player timestamp</button>`:''}<p class="help margintop">Video stays on your device. Only your review notes persist; reopening the app requires re-selecting the file.</p></div></section><section class="panel"><div class="panel-header"><h3 class="panel-title">ADD DECISION OBSERVATION</h3><span class="tinycaps">0–4 RUBRIC</span></div><div class="panel-body"><form id="review-form" class="stack"><div class="form-grid"><div class="field"><label for="review-time">Video timestamp (mm:ss)</label><input id="review-time" name="timestamp" placeholder="05:24" value="${formatClock(ui.videoTime)}" required pattern="[0-9]{1,3}:[0-5][0-9]"/></div><div class="field"><label for="review-rating">Decision quality</label><select name="rating" id="review-rating"><option value="4">4 · Excellent</option><option value="3">3 · Sound</option><option value="2" selected>2 · Mixed</option><option value="1">1 · Significant error</option><option value="0">0 · Major error</option></select></div></div><div class="field"><label for="review-metric">Primary ADC metric</label><select name="metricId" id="review-metric">${metricList}</select></div><div class="form-grid"><div class="field"><label for="review-cause">Primary reason</label><select name="cause" id="review-cause"><option value="Decision-making">Decision-making</option><option value="Knowledge gap">Knowledge gap</option><option value="Mechanical execution">Mechanical execution</option><option value="Attention">Attention / information</option><option value="No significant error">No significant error</option></select></div><div class="field"><label for="review-confidence">Evidence confidence</label><select name="confidence" id="review-confidence"><option value="High">High</option><option value="Medium" selected>Medium</option><option value="Low">Low / uncertain</option></select></div></div><div class="field"><label for="review-decision">Information, decision and better alternative</label><textarea name="note" id="review-decision" required minlength="12" placeholder="At 17:52, my Flash was down and enemy jungler was missing. I overextended for a side wave. Better: take the safe mid wave and wait for vision."></textarea></div><button class="btn wide" type="submit">${icon('plus',14)} Save review observation</button></form><div class="note margintop">A review observation is a self-assessment, not an automatically verified dodge or certified metric trial. Evaluate the information available before the outcome.</div></div></section></div><div class="grid cols2 margintop">${section('REVIEW TIMELINE',reviews.length?reviews.slice(0,18).map(r=>`<div class="review-card"><div class="flat-row"><strong class="tint">${safe(r.timestamp)}</strong><span class="chip ${reviewSuccess(r)?'success':'warn'}">${r.rating}/4</span></div><div class="tinycaps" style="margin-top:6px">${safe(metricById(r.metricId)?.name||r.metricId)}</div><p>${safe(r.note)}</p><div class="flat-row"><span class="help">${safe(r.confidence)} confidence · ${safe(r.cause)}</span><button class="text-action" data-action="delete-review" data-id="${r.id}">DELETE</button></div></div>`).join(''):empty('Nothing reviewed yet','Select a decision in your gameplay video and create the first evidence note.'),`<span class="tinycaps">${reviews.length} OBSERVATIONS</span>`)}${section('COACHING RULES',`<div class="step"><div class="step-num">1</div><div><strong>Pause before the outcome</strong><p>Reconstruct the visible threats, resources and reasonable alternatives.</p></div></div><div class="step"><div class="step-num">2</div><div><strong>Tag the primary metric</strong><p>Choose one metric to prevent counting the same decision multiple times.</p></div></div><div class="step"><div class="step-num">3</div><div><strong>Separate judgment from results</strong><p>A failed play may have been justified; a winning play may be flawed.</p></div></div><div class="step"><div class="step-num">4</div><div><strong>Train the correction</strong><p>Set a reviewed weakness as the next daily training focus.</p></div></div>`)} </div>`;}
function formatClock(seconds){let t=Math.max(0,Math.floor(+seconds||0));return `${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toString().padStart(2,'0')}`;}
function insightsPage(){const matches=getMatches(),samples=matches.slice(0,12).reverse(),bad=state.reviews.filter(r=>Number(r.rating)<3),reviewed=state.reviews.length;const groups=Object.entries(bad.reduce((acc,r)=>{acc[r.metricId]=(acc[r.metricId]||0)+1;return acc;},{})).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...samples.map(m=>(+m.cs/Math.max(1,+m.duration))));return `${pageIntro('POST-GAME / PATTERN RECOGNITION','Performance Insights','Track what is improving, where the evidence is thin and which decisions deserve the next training cycle.',`<button class="btn" data-nav="vod">${icon('video',15)} Review a game</button>`)}<div class="grid cols4 marginbottom">${stat('Matches tracked',fmt(matches.length),'Entire local archive')}${stat('Successful reviewed decisions',reviewed?percent(state.reviews.filter(reviewSuccess).length,reviewed).toFixed(0)+'%':'—','Self-reviewed opportunities')}${stat('Documented metric gates',ALL.filter(m=>certified(m.id)>=0).length+'/45','At least F complete')}${stat('Pending tier assessments',state.assessments.length,'Self-recorded attempts')}</div><div class="grid cols2">${section('CS / MIN PER MATCH',samples.length?`<div class="chart-bars">${samples.map((m,i)=>`<div class="chart-column"><span class="chart-label">${(+m.cs/Math.max(1,+m.duration)).toFixed(1)}</span><div class="chart-bar" style="height:${Math.max(5,(+m.cs/Math.max(1,+m.duration))/max*117)}px" title="${safe(m.champion)} · ${safe(m.date)}"></div><span class="chart-label">${i+1}</span></div>`).join('')}</div><p class="help margintop">Match sequence (oldest → newest). CS/min measures farming output, not wave-decision mastery.</p>`:empty('No match trend yet','Log matches to visualize your farming trend.'))}${section('RECURRING REVIEW ISSUES',groups.length?groups.slice(0,7).map(([key,n])=>`<div class="list-row"><div class="list-row-main"><strong>${safe(metricById(key)?.name||key)}</strong><p>${safe(metricById(key)?.componentName||'')} · ${n} reviewed errors</p></div><button class="btn sm ghost" data-action="focus-metric" data-id="${safe(key)}">TRAIN</button></div>`).join(''):empty('No recurring errors recorded','The Mistake Library builds from your own VOD observations. Review both successful and unsuccessful decisions.'),`<span class="tinycaps">${bad.length} TAGGED ERRORS</span>`)}${section('ATTRIBUTE CERTIFICATION',ATTRS.map(a=>{const pass=a.components.flatMap(c=>c.metrics).filter(m=>certified(m.id)>=0).length;return `<div class="list-row"><div class="list-row-main"><strong>${safe(a.name)}</strong><p>${pass}/9 metrics passed F gate</p><div class="progress-track" style="margin-top:8px"><div class="progress-fill" style="width:${pass/9*100}%"></div></div></div>${rankTag(attributeRank(a))}</div>`}).join(''))}${section('NEXT COACHING DECISION',groups.length?`<div class="eyebrow">LEADING REVIEW TARGET</div><h2 class="margintop">${safe(metricById(groups[0][0])?.name||groups[0][0])}</h2><p class="metric-desc margintop">This metric accounts for ${groups[0][1]} of your ${bad.length} currently tagged negative observations. That is a review frequency, not a true error rate unless all eligible opportunities were sampled.</p><button class="btn margintop" data-action="focus-metric" data-id="${safe(groups[0][0])}">Set as training focus</button>`:empty('Collect decision evidence','Review at least a few real gameplay decisions. ARISE will surface recurring weaknesses without inventing missing data.'))}</div>`;}
function settingsPage(){const p=state.profile;return `${pageIntro('LOCAL PROFILE / DATA CONTROL','Settings','Your personal ADC training tool is completely separate from ARISE. Control your champion pool and export or restore your training history.',`<button class="btn" data-action="export-json">${icon('download',14)} Export backup</button>`)}<div class="grid cols2">${section('PERSONAL PROFILE',`<form id="profile-form" class="stack"><div class="field"><label for="riot-id">Riot ID (optional, for your records)</label><input id="riot-id" name="riotId" value="${safe(p.riotId)}" placeholder="GameName#TAG" maxlength="80"/></div><div class="form-grid"><div class="field"><label for="region">Platform</label><select name="region" id="region">${['EUW','EUNE','NA','KR','BR','LAN','LAS','TR','RU','OCE','JP','PH','SG','TH','TW','VN','ME'].map(x=>`<option value="${x}" ${p.region===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="goal">Competitive goal</label><select name="goal" id="goal">${['GOLD','PLATINUM','EMERALD','DIAMOND','MASTER','GRANDMASTER','CHALLENGER'].map(x=>`<option value="${x}" ${p.goal===x?'selected':''}>${x}</option>`).join('')}</select></div></div><button type="submit" class="btn">Save profile</button></form>`)}${section('CHAMPION POOL',`<div class="stack">${[['primary','Primary champion'],['secondary','Secondary champion'],['flex','Optional flex champion']].map(([key,label])=>`<div class="field"><label for="pool-${key}">${label}</label><select id="pool-${key}" data-pool="${key}">${key==='flex'?'<option value="">No flex champion</option>':''}${CHAMPIONS.map(c=>`<option value="${safe(c.name)}" ${p[key]===c.name?'selected':''}>${safe(c.name)} · ${safe(c.type)}</option>`).join('')}</select></div>`).join('')}<div class="note">Champion changes preserve historical assessments for prior champions. Contracts don't count as Riot champion mastery points.</div></div>`)}${section('BACKUP & RESTORE',`<p class="metric-desc">Export saves matches, training quests, assessment evidence and VOD review notes into one JSON file. Actual videos are never included.</p><div class="actions margintop"><button class="btn" data-action="export-json">${icon('download',14)} Export JSON</button><button class="btn ghost" data-action="import-backup">Import JSON</button></div><hr class="separator"><p class="help">LocalStorage persists in this browser and origin only. Use a backup before clearing browser data or moving devices.</p>`)}${section('TOOLS & RESET',`<div class="stack"><div><strong class="small">Try the interface</strong><p class="help margintop">Load an explicitly labeled fictional sample profile to explore all modules.</p><button class="btn ghost margintop" data-action="load-demo">Load demonstration data</button></div><hr class="separator"><div><strong class="small bad">Clear personal data</strong><p class="help margintop">Deletes locally stored matches, reviews and assessments. Export first if you want a backup.</p><button class="btn danger margintop" data-action="reset-data">${icon('trash',14)} Reset this app</button></div></div>`)} </div><div class="note margintop">Automatic Riot match sync and recording are available in the Windows desktop companion through Capture Studio. Enter a Riot ID and a local Riot Developer API key. Full 45-metric automatic decision assessment is not available.</div>`;}
function championOptions(selected){return CHAMPIONS.map(c=>`<option value="${safe(c.name)}" ${c.name===selected?'selected':''}>${safe(c.name)}</option>`).join('');}
function openModal(type,opts={}){ui.modal={type,...opts};renderModal();}
function renderModal(){const root=$('#modal-root');if(!root)return;if(!ui.modal){root.innerHTML='';return;}const x=ui.modal,close=`<button class="close-icon" aria-label="Close dialog" data-action="close-modal">×</button>`;let title='',body='';if(x.type==='match'){title='LOG A MATCH';body=`<form id="match-form" class="stack"><div class="form-grid"><div class="field"><label>Match date</label><input required type="date" name="date" value="${today()}"/></div><div class="field"><label>Champion</label><select name="champion">${championOptions(state.profile.primary)}</select></div><div class="field"><label>Result</label><select name="result"><option value="win">Victory</option><option value="loss">Defeat</option></select></div><div class="field"><label>Duration (minutes)</label><input required name="duration" type="number" step="0.1" min="5" max="150" value="30"/></div><div class="field"><label>CS</label><input required name="cs" type="number" min="0" max="1000" value="210"/></div><div class="field"><label>Kills</label><input required name="kills" type="number" min="0" max="100" value="5"/></div><div class="field"><label>Deaths</label><input required name="deaths" type="number" min="0" max="100" value="4"/></div><div class="field"><label>Assists</label><input required name="assists" type="number" min="0" max="100" value="8"/></div></div><div class="field"><label>One lesson from this match (optional)</label><textarea name="note" placeholder="Describe an important decision or mistake."></textarea></div><div class="modal-footer"><button class="btn ghost" type="button" data-action="close-modal">Cancel</button><button class="btn" type="submit">Save match</button></div></form>`;}
else if(x.type==='assessment'){const tier=TIERS[x.tier],champ=x.key.startsWith('C:');let titleText=champ?`${x.key.split(':').slice(1,-1).join(':')} / C${x.key.split(':').at(-1)}`:metricById(x.key)?.name||x.key;title='RECORD A MASTERY TRIAL';body=`<div class="note marginbottom">${safe(titleText)} · <b>${safe(tier.name)} difficulty</b>. Record genuine eligible opportunities, not entire games. Self-recorded results remain provisional.</div><form id="assessment-form" class="stack"><div class="field"><label>Assessed tier</label><select name="tier">${TIERS.map((t,i)=>`<option value="${i}" ${i===x.tier?'selected':''}>${safe(t.name)} · ${t.accuracy}% / ${t.count} opportunities / ${t.sessions} sessions</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label>Successful opportunities</label><input required type="number" name="successes" min="0" max="1000" value="${tier.count}"/></div><div class="field"><label>Total eligible opportunities</label><input required type="number" name="opportunities" min="1" max="1000" value="${tier.count}"/></div><div class="field"><label>Separate assessment sessions</label><input required type="number" name="sessions" min="1" max="100" value="${tier.sessions}"/></div><div class="field"><label>Evidence source</label><select name="source"><option value="Self-reviewed VOD">Self-reviewed VOD</option><option value="Controlled drill">Controlled drill</option><option value="Scenario assessment">Scenario assessment</option><option value="Coach-reviewed (self-attested)">Coach-reviewed (self-attested)</option></select></div></div><div class="field"><label>What evidence supports this attempt?</label><textarea name="note" required minlength="8" placeholder="VOD timestamp(s), drill setup, difficulty and what was assessed."></textarea></div><div class="modal-footer"><button class="btn ghost" type="button" data-action="close-modal">Cancel</button><button class="btn" type="submit">Record result</button></div></form>`;}
else if(x.type==='match-detail'){const m=state.matches.find(y=>y.id===x.id);if(!m){ui.modal=null;renderModal();return;}title=`MATCH · ${safe(m.champion)}`;body=`<div class="grid cols2"><div class="data-pill">${safe(m.date)}</div><div class="data-pill">${m.win?'VICTORY':'DEFEAT'}</div><div class="data-pill">KDA · ${m.kills}/${m.deaths}/${m.assists}</div><div class="data-pill">CS/M · ${(+m.cs/Math.max(1,+m.duration)).toFixed(2)}</div></div><p class="metric-desc margintop">${safe(m.note||'No notes for this match.')}</p><p class="help margintop">${m.riotMatchId?'Riot match ID: '+safe(m.riotMatchId):'Manually recorded match'}</p>${m.signals?'<div class="grid cols2 margintop">'+Object.entries(m.signals).filter(([k,v])=>Number.isFinite(v)&&k!=='gamesTracked').slice(0,12).map(([k,v])=>`<div class="data-pill">${safe(k)} · ${safe(v)}</div>`).join('')+'</div><p class="help">Automatic Riot performance indicators; not skill-quality scores.</p>':''}<div class="modal-footer"><button class="btn danger" data-action="delete-match" data-id="${m.id}">${icon('trash',14)} Delete match</button><button class="btn ghost" data-action="close-modal">Close</button></div>`;}
else if(x.type==='riot-pick'){const data=ui.importJson;if(!data){ui.modal=null;return;}title='SELECT YOUR MATCH PARTICIPANT';body=`<p class="metric-desc marginbottom">Select your player record from the Riot match-v5 JSON file. The import uses your selected participant's actual outcome and match statistics.</p><form id="riot-import-form" class="stack"><div class="field"><label>Participant</label><select name="index">${data.info.participants.map((p,i)=>`<option value="${i}" ${(p.individualPosition==='BOTTOM'||p.teamPosition==='BOTTOM')?'':' '}>${safe(p.riotIdGameName||p.summonerName||'Player '+(i+1))} · ${safe(p.championName||'')} · ${safe(p.teamPosition||p.individualPosition||'?')}</option>`).join('')}</select></div><div class="modal-footer"><button class="btn ghost" type="button" data-action="close-modal">Cancel</button><button class="btn" type="submit">Import match</button></div></form>`;}
else if(x.type==='backup'){title='RESTORE BACKUP';body=`<div class="note warning marginbottom">Restoring a backup will replace all locally stored app data. Export your current data first.</div><div class="field"><label for="backup-input">ADC ASCENT JSON backup</label><input id="backup-input" type="file" accept="application/json,.json"/></div><div class="modal-footer"><button class="btn ghost" data-action="close-modal">Cancel</button></div>`;}
else if(x.type==='pool'){title='MANAGE CHAMPION POOL';body=`<p class="metric-desc marginbottom">Two core champions plus one optional flex. Champion-specific contracts are retained when you switch your active pool.</p><form id="pool-form" class="stack">${[['primary','Primary champion'],['secondary','Secondary champion'],['flex','Optional flex champion']].map(([key,label])=>`<div class="field"><label>${label}</label><select name="${key}">${key==='flex'?'<option value="">None</option>':''}${championOptions(state.profile[key])}</select></div>`).join('')}<div class="modal-footer"><button type="button" class="btn ghost" data-action="close-modal">Cancel</button><button class="btn" type="submit">Save champion pool</button></div></form>`;}
root.innerHTML=`<div class="modal-layer" role="presentation" data-action="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-header"><h2>${title}</h2>${close}</div><div class="modal-body">${body}</div></div></div>`;}
function completeMatchQuests(date){const target=state.quests.find(q=>q.date===date&&q.index===1&&!q.done);if(target){target.done=true;toast('Match logged · training quest complete');}}
function completeReviewQuests(){const task=state.quests.find(q=>q.date===today()&&q.index===2&&!q.done);if(task){task.done=true;toast('Review saved · training quest complete');}}
function recordMatch(entry){if(entry.riotMatchId&&state.matches.some(m=>m.riotMatchId===entry.riotMatchId)){toast('This Riot match has already been imported.');return false;}state.matches.push(entry);completeMatchQuests(entry.date);save();ui.modal=null;render();toast('Match saved to your private archive');return true;}
function download(name,content,mime){const blob=new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function loadDemo(){state=initial();state.profile.riotId='SamplePlayer#ADC';const champs=['Jinx',"Kai'Sa",'Ezreal'];for(let i=0;i<11;i++){let date=new Date();date.setDate(date.getDate()-Math.floor(i/2));const win=[true,false,true,true,false,true,false,true,true,false,true][i];state.matches.push({id:uid(),date:date.toLocaleDateString('en-CA'),champion:champs[i%3],win,kills:3+i%8,deaths:2+i%5,assists:4+i%11,cs:178+i*9,duration:25+i%9,note:'Fictional demonstration data',demo:true});}for(let i=0;i<8;i++){state.reviews.push({id:uid(),timestamp:`${String(6+i*2).padStart(2,'0')}:24`,metricId:['LAN-03.2','MAC-02.1','TFC-01.2','MEC-03.2'][i%4],rating:i%3===0?3:1,cause:'Decision-making',confidence:'Medium',note:'Illustrative decision note generated for demo mode. Not actual gameplay evidence.',createdAt:new Date().toISOString(),date:today(),demo:true});}state.settings.focusMetric='TFC-01.2';createQuests();state.quests.slice(0,2).forEach(q=>q.done=true);save();ui.champion='Jinx';ui.page='overview';ui.modal=null;render();toast('Sample data loaded — fictional demonstration');}
function parseRiotJSON(json){const data=(json?.data?.info?.participants)?json.data:json;if(!data?.info?.participants||!Array.isArray(data.info.participants)||!data.info.participants.length||!data.info.gameDuration)throw new Error('Not a valid match-v5 match JSON response');return data;}
function importParticipant(index){const data=ui.importJson;const p=data?.info?.participants?.[index];if(!p)return toast('Choose a valid participant');const millis=data.info.gameDuration>30000?data.info.gameDuration/1000:data.info.gameDuration;const stamp=new Date(data.info.gameEndTimestamp||data.info.gameCreation||Date.now());const matchId=data.metadata?.matchId||null;const obj={id:uid(),riotMatchId:matchId,date:stamp.toLocaleDateString('en-CA'),champion:p.championName||'Unknown',win:!!p.win,kills:+p.kills||0,deaths:+p.deaths||0,assists:+p.assists||0,cs:(+p.totalMinionsKilled||0)+(+p.neutralMinionsKilled||0),duration:Math.max(1,millis/60),note:'Imported from Riot match-v5 JSON. Match decision quality remains unassessed.',source:'riot-json'};ui.importJson=null;recordMatch(obj);}
const fileRead=(file,callback)=>{if(!file)return;const reader=new FileReader();reader.onload=()=>{try{callback(JSON.parse(String(reader.result)));}catch(e){toast('Could not read JSON: '+(e.message||'invalid file'));}};reader.onerror=()=>toast('File could not be read');reader.readAsText(file);};
function importBackup(json){if(!json||json.version!==1||!json.profile||!Array.isArray(json.matches)||!Array.isArray(json.quests)||!Array.isArray(json.reviews)||!Array.isArray(json.assessments)||!json.settings)throw Error('File is not an ADC ASCENT v1 backup');state=json;save();ui.modal=null;ui.champion=state.profile.primary;render();toast('Backup restored');}
function safeRecordAssessment(form){const x=ui.modal,fd=new FormData(form),tier=cap(fd.get('tier'),0,9),successes=Number(fd.get('successes')),opportunities=Number(fd.get('opportunities')),sessions=Number(fd.get('sessions'));if(!Number.isInteger(successes)||!Number.isInteger(opportunities)||successes<0||opportunities<1||successes>opportunities||!Number.isInteger(sessions)||sessions<1){toast('Check observation and session counts');return;}const a={id:uid(),key:x.key,tier,successes,opportunities,sessions,source:String(fd.get('source')||''),note:String(fd.get('note')||'').trim(),date:today(),createdAt:new Date().toISOString()};if(a.note.length<8){toast('Describe supporting evidence');return;}state.assessments.push(a);save();ui.tier=tier;ui.modal=null;render();toast(qualificationFor(a.key,a.tier)?'Assessment meets numerical gate · self-attested':'Assessment recorded · gate requirements not yet met');}
// Action event delegation; all interaction remains fully local.
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){goto(nav.dataset.nav);return;}const att=e.target.closest('[data-attr]');if(att){ui.attr=att.dataset.attr;ui.metricId=ATTRS.find(a=>a.id===ui.attr).components[0].metrics[0].id;ui.tier=0;render();return;}const me=e.target.closest('[data-metric]');if(me){ui.metricId=me.dataset.metric;ui.tier=Math.max(0,Math.min(9,certified(ui.metricId)+1));render();return;}const tier=e.target.closest('[data-tier]');if(tier){ui.tier=Number(tier.dataset.tier);render();return;}const ch=e.target.closest('[data-champion]');if(ch){ui.champion=ch.dataset.champion;ui.championContractIndex=0;ui.tier=0;render();return;}const contract=e.target.closest('[data-contract]');if(contract){ui.championContractIndex=Number(contract.dataset.contract);ui.tier=0;render();return;}const act=e.target.closest('[data-action]');if(!act)return;const action=act.dataset.action,id=act.dataset.id;if(action==='modal-backdrop'){if(e.target===act){ui.modal=null;renderModal();}return;}if(action==='close-modal'){ui.modal=null;renderModal();return;}if(action==='toggle-menu'){ui.menu=!ui.menu;render();return;}if(action==='close-menu'){ui.menu=false;render();return;}if(action==='add-match'){openModal('match');return;}if(action==='edit-pool'){openModal('pool');return;}if(action==='assess-metric'){openModal('assessment',{key:id,tier:ui.tier});return;}if(action==='assess-contract'){openModal('assessment',{key:id,tier:ui.tier});return;}if(action==='focus-metric'){if(!metricById(id)){toast('Choose a valid metric');return;}state.settings.focusMetric=id;save();goto('training');toast('Training focus updated');return;}if(action==='generate-training'){const exists=state.quests.some(q=>q.date===today());if(exists&&!confirm('Replace today\'s training checklist? Previously completed quests today will be replaced.'))return;createQuests();render();toast('Your daily training plan is ready');return;}if(action==='delete-assessment'){if(!confirm('Delete this assessment?'))return;state.assessments=state.assessments.filter(a=>a.id!==id);save();render();return;}if(action==='delete-review'){if(!confirm('Delete this review observation?'))return;state.reviews=state.reviews.filter(a=>a.id!==id);save();render();return;}if(action==='match-detail'){openModal('match-detail',{id});return;}if(action==='delete-match'){if(!confirm('Delete this match from your archive?'))return;state.matches=state.matches.filter(m=>m.id!==id);save();ui.modal=null;render();return;}if(action==='riot-json'){const inp=el('input',{type:'file',accept:'.json,application/json'});inp.onchange=()=>fileRead(inp.files?.[0],data=>{try{ui.importJson=parseRiotJSON(data);openModal('riot-pick');}catch(error){toast(error.message);}});inp.click();return;}if(action==='export-json'){download(`adc-ascent-backup-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('Backup exported');return;}if(action==='export-csv'){const rows=[['date','champion','result','kills','deaths','assists','cs','duration_minutes','riot_match_id'],...getMatches().map(m=>[m.date,m.champion,m.win?'Win':'Loss',m.kills,m.deaths,m.assists,m.cs,m.duration,m.riotMatchId||''])];const csv=rows.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n');download(`adc-ascent-matches-${today()}.csv`,csv,'text/csv');return;}if(action==='import-backup'){openModal('backup');return;}if(action==='load-demo'){if(!confirm('Replace current local data with fictional example data? Export a backup first if needed.'))return;loadDemo();return;}if(action==='reset-data'){if(!confirm('Permanently delete all locally saved ADC ASCENT data?'))return;state=initial();save();ui.champion=state.profile.primary;goto('overview');toast('Local data reset');return;}if(action==='capture-time'){const v=$('#vod-video');if(!v)return;$('#review-time').value=formatClock(v.currentTime);toast('Video timestamp captured');return;}if(action==='clear-video'){if(ui.videoUrl)URL.revokeObjectURL(ui.videoUrl);ui.videoUrl=null;ui.videoFile=null;ui.videoName='';ui.videoTime=0;render();return;}});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-quest]')){const item=state.quests.find(q=>q.id===t.dataset.quest);if(!item)return;if(t.checked&&item.index===3&&!String(item.reflection||'').trim()){t.checked=false;toast('Write a reflection before completing this quest');return;}item.done=!!t.checked;save();render();return;}if(t.id==='focus-select'){if(metricById(t.value)){state.settings.focusMetric=t.value;save();render();toast('Focus updated. Generate a mission to apply it.');}return;}if(t.dataset.change==='reflection'){const item=state.quests.find(q=>q.date===today()&&q.index===3);if(item){item.reflection=t.value;save();}return;}if(t.dataset.change==='review-match'){ui.selectedMatch=t.value;return;}if(t.dataset.pool){const key=t.dataset.pool,val=t.value;const vals={...state.profile,[key]:val};if(vals.primary===vals.secondary||(vals.flex&&(vals.flex===vals.primary||vals.flex===vals.secondary))){t.value=state.profile[key];toast('Choose different champions for each slot');return;}state.profile[key]=val;if(key==='primary')ui.champion=val;save();render();toast('Champion pool updated');return;}if(t.id==='vod-file'){const file=t.files?.[0];if(!file)return;if(!/^(video\/mp4|video\/webm|video\/ogg)$/.test(file.type)){toast('Choose an MP4, WebM or Ogg video');return;}if(ui.videoUrl)URL.revokeObjectURL(ui.videoUrl);ui.videoUrl=URL.createObjectURL(file);ui.videoFile=file;ui.videoName=file.name;ui.videoTime=0;render();toast('Video loaded locally — no upload');return;}if(t.id==='backup-input'){fileRead(t.files?.[0],data=>{try{importBackup(data);}catch(err){toast(err.message);}});return;}});
document.addEventListener('submit',e=>{const form=e.target;if(!['match-form','profile-form','pool-form','assessment-form','riot-import-form','review-form'].includes(form.id))return;e.preventDefault();const d=new FormData(form);if(form.id==='match-form'){const m={id:uid(),date:String(d.get('date')),champion:String(d.get('champion')),win:d.get('result')==='win',duration:Number(d.get('duration')),cs:Number(d.get('cs')),kills:Number(d.get('kills')),deaths:Number(d.get('deaths')),assists:Number(d.get('assists')),note:String(d.get('note')||''),source:'manual'};if(!m.date||m.duration<5||m.duration>150||!championByName(m.champion)||![m.cs,m.kills,m.deaths,m.assists].every(x=>Number.isInteger(x)&&x>=0)){toast('Please check your match fields');return;}recordMatch(m);return;}if(form.id==='profile-form'){state.profile.riotId=String(d.get('riotId')||'').trim();state.profile.region=String(d.get('region'));state.profile.goal=String(d.get('goal'));save();render();toast('Profile updated');return;}if(form.id==='pool-form'){const vals={primary:String(d.get('primary')),secondary:String(d.get('secondary')),flex:String(d.get('flex')||'')};if(!vals.primary||!vals.secondary||vals.primary===vals.secondary||(vals.flex&&(vals.flex===vals.primary||vals.flex===vals.secondary))){toast('Choose distinct primary, secondary and flex champions');return;}Object.assign(state.profile,vals);ui.champion=vals.primary;ui.modal=null;save();render();toast('Champion pool saved');return;}if(form.id==='assessment-form'){safeRecordAssessment(form);return;}if(form.id==='riot-import-form'){importParticipant(Number(d.get('index')));return;}if(form.id==='review-form'){const note=String(d.get('note')||'').trim();const timestamp=String(d.get('timestamp')||'');const metricId=String(d.get('metricId'));if(note.length<12||!metricById(metricId)||!/^[0-9]{1,3}:[0-5][0-9]$/.test(timestamp)){toast('Add a valid timestamp, metric and decision description');return;}state.reviews.push({id:uid(),timestamp,metricId,rating:Number(d.get('rating')),cause:String(d.get('cause')),confidence:String(d.get('confidence')),note,matchId:ui.selectedMatch||null,videoName:ui.videoName||null,createdAt:new Date().toISOString(),date:today(),source:'self_review'});completeReviewQuests();save();render();toast('Review observation saved');return;}});

document.addEventListener('adc:riot-sync',event=>{
 const data=event.detail;
 if(!Array.isArray(data?.matches))return;
 let added=0,updated=0;
 for(const m of data.matches){
  const p=m.info?.participants?.find(p=>p.puuid===data.puuid);
  if(!p)continue;
  const id=String(m.metadata?.matchId||m.info?.gameId||'');if(!id)continue;
  const duration=Number(m.info.gameDuration)||0;if(duration<300)continue;
  const old=state.matches.find(x=>x.riotMatchId===id);
  const entry=window.ADC_INTELLIGENCE?.extract(m);
  if(old){const details=window.ADC_ANALYTICS?.enrich(p,m.info)||null;if(entry&&!old.signals){Object.assign(old,{signals:entry.signals,patch:entry.patch,queueId:entry.queueId});updated++;}if(details&&!old.detail){old.detail=details;updated++;}continue;}
  state.matches.push({id:uid(),date:new Date(m.info.gameEndTimestamp||m.info.gameCreation||Date.now()).toLocaleDateString('en-CA'),champion:p.championName,win:!!p.win,duration:duration>100000?duration/60000:duration/60,cs:(p.totalMinionsKilled||0)+(p.neutralMinionsKilled||0),kills:p.kills||0,deaths:p.deaths||0,assists:p.assists||0,note:'Automatically imported from Riot match-v5; skill decisions still require evidence',riotMatchId:id,source:'riot_api',detail:window.ADC_ANALYTICS?.enrich(p,m.info)||{},signals:entry?.signals||{},patch:entry?.patch||'',queueId:entry?.queueId||null,role:m.info.role||p.teamPosition||p.individualPosition||'UNKNOWN',isADC:m.info.isADC!==undefined?!!m.info.isADC:(p.teamPosition==='BOTTOM'||p.individualPosition==='BOTTOM')});added++;
 }
 state.timelineCandidates=[...new Map([...(state.timelineCandidates||[]),...(data.timelineCandidates||[])].map(x=>[String(x.matchId||'')+'|'+String(x.id||x.startMs),x])).values()].slice(-1200);
 if(data.gameName&&data.tagLine)state.profile.riotId=data.gameName+'#'+data.tagLine;
 state.settings.lastRiotSync=new Date().toISOString();
 save();render();if(added||updated)toast(`Auto-sync: ${added} new matches, ${updated} enriched records`);
});
document.addEventListener('adc:riot-profile',event=>{const p=event.detail;if(!p?.gameName||!p?.tagLine)return;state.profile.riotId=p.gameName+'#'+p.tagLine;state.profile.region=({EUW1:'EUW',EUN1:'EUNE',NA1:'NA',OC1:'OCE',BR1:'BR',JP1:'JP',KR:'KR',TR1:'TR',LA1:'LAN',LA2:'LAS'}[p.region]||p.region||state.profile.region);state.profile.summonerLevel=p.summonerLevel??null;state.profile.profileIconId=p.profileIconId??null;state.profile.ranked=Array.isArray(p.ranked)?p.ranked:[];state.settings.profileVerifiedAt=new Date().toISOString();save();if(ui.page!=='recorder')render();});
document.addEventListener('adc:timeline-candidates',event=>{state.timelineCandidates=event.detail?.candidates||[];save();});

window.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){ui.modal=null;renderModal();}});
window.addEventListener('hashchange',()=>{const hash=location.hash.replace('#','');if(hash&&hash!==ui.page){ui.page=navs.some(n=>n[0]===hash)?hash:'overview';ui.menu=false;ui.modal=null;render();}});
// Dynamic select values after each render; not user-generated HTML state.
const origRender=render;render=function(){origRender();const f=$('#focus-select');if(f)f.value=state.settings.focusMetric;const s=$('#review-match');if(s)s.value=ui.selectedMatch||'';const r=$('#review-metric');if(r)r.value=state.settings.focusMetric;};
ui.champion=state.profile.primary||'Jinx';ui.page=navs.some(n=>n[0]===location.hash.replace('#',''))?location.hash.replace('#',''):'overview';render();
window.adcAppRender=render;
if('serviceWorker' in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();
